import json
from decimal import Decimal, getcontext

getcontext().prec = 90

def f(x):
    # (1+x)^(1/x) computed as exp(ln(1+x)/x)
    return ((1 + x).ln() / x).exp()

def g(x):
    # (1+2x)^(1/(2x)) computed as exp(ln(1+2x)/(2x))
    return ((1 + 2 * x).ln() / (2 * x)).exp()

e_val = Decimal(1).exp()
target = e_val / 2

samples = []
for k in (6, 10, 15, 20):
    x = Decimal(10) ** (-k)
    val = (f(x) - g(x)) / x
    samples.append({"x": str(x), "value": format(val, ".25f")})

last = (f(Decimal(10) ** -20) - g(Decimal(10) ** -20)) / Decimal(10) ** -20
err = abs(last - target)

if err < Decimal("1e-12"):
    final = "e/2"
else:
    final = "UNSUPPORTED"

print(json.dumps({
    "final_answer": final,
    "evidence": {
        "target_e_over_2": format(target, ".25f"),
        "samples": samples,
        "abs_error_at_x_1e-20": format(err, ".3E"),
        "method": "exp(ln(1+x)/x) expansion: e(1 - x/2 + ...) minus e(1 - x + ...) gives e*x/2 + O(x^2)"
    }
}))
